import styled from '@emotion/styled';
import { Paragraph } from 'components/UI';

interface LeftImageProps {
  $variant?: 'country' | 'brand';
}

export const LeftImgComponent = styled.div({
  display: 'flex',
  gap: '12px',
  alignItems: 'center',
  maxWidth: '100%',
});

export const LeftImgBox = styled.div({
  width: '32px',
  height: '32px',
  borderRadius: '100%',
  overflow: 'hidden',
  flexShrink: 0,
});

export const BrandImgBox = styled.div({
  width: '40px',
  height: '32px',
  borderRadius: '2px',
  overflow: 'hidden',
  flexShrink: 0,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
});

export const LeftImage = styled('img', {
  shouldForwardProp: (propName) => propName !== '$variant',
})<LeftImageProps>(({ $variant = 'country' }) => ({
  height: '100%',
  maxHeight: '100% !important',
  objectFit: 'cover',
  ...($variant === 'country' && {
    width: '100%',
    objectFit: 'cover',
  }),
  ...($variant === 'brand' && {
    width: 'auto',
    maxWidth: '100%',
    objectFit: 'contain',
  }),
}));

export const TruncatedText = styled(Paragraph)({
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  maxWidth: '100%',
  flexShrink: 1,
  minWidth: 0,
});
